package com.edgecloud.alert.dto;
import java.time.Instant; import java.util.UUID; import com.edgecloud.alert.entity.*;
public record MaintenanceWindowResponse(UUID id,UUID projectId,MaintenanceScopeType scopeType,UUID serviceId,String deviceId,String name,String reason,Instant startsAt,Instant endsAt,boolean enabled,String status,UUID createdByUserId,Instant createdAt,Instant updatedAt,long suppressionCount){public static MaintenanceWindowResponse from(MaintenanceWindow w,Instant now,long count){String status=!w.isEnabled()?"DISABLED":now.isBefore(w.getStartsAt())?"UPCOMING":now.isBefore(w.getEndsAt())?"ACTIVE":"EXPIRED";return new MaintenanceWindowResponse(w.getId(),w.getProjectId(),w.getScopeType(),w.getServiceId(),w.getDeviceId(),w.getName(),w.getReason(),w.getStartsAt(),w.getEndsAt(),w.isEnabled(),status,w.getCreatedByUserId(),w.getCreatedAt(),w.getUpdatedAt(),count);}}
